struct ring {
  atomic_size_t head; // consumer
  atomic_size_t tail; // producer
  T buf[N];  // N = 2^k
};

t = load_relaxed(&r->tail);
h = load_acquire(&r->head);
if (t - h == N) return FULL;
r->buf[t & (N-1)] = x;
store_release(&r->tail, t+1);

h = load_relaxed(&r->head);
t = load_acquire(&r->tail);
if (h == t) return EMPTY;
x = r->buf[h & (N-1)];
store_release(&r->head, h+1);
